import json,pathlib
P=pathlib.Path('research/asia');r=json.load(open(P/'reviews.json'));manifest=json.load(open(P/'manifest.json'));extra=P/'extra';extra.mkdir(exist_ok=True)
base='https://olympiads.hbcse.tifr.res.in/wp-content/uploads/2026/10/'
urls={2017:base+'sol-inmo_17.pdf',2019:base+'Inmo-2019-Solutions.pdf',2020:base+'sol-inmo-20.pdf',2021:base+'INMO_2021_solutions.pdf',2024:base+'INMO_2024_final_solutions.pdf'}
def add(id,diff,reason,sol='',topic=None,subtopics=None,**kw):
 r[id]={'difficulty':diff,'reason':reason,'proofConfidence':'checked' if diff is not None else 'unresolved',**kw}
 if sol:r[id]['solutionOverride']=sol
 if topic:r[id]['topic']=topic
 if subtopics:r[id]['subtopics']=subtopics;r[id]['tags']=subtopics
 if id.startswith('ind_') and int(id[4:8]) in urls and not kw.get('competitionOverride')=='Indian team selection tests':
  r[id].setdefault('competitionOverride','Indian National Mathematical Olympiad (INMO)');r[id].setdefault('sourceUrl',urls[int(id[4:8])]);r[id].setdefault('solutionUrl',urls[int(id[4:8])]);r[id].setdefault('solutionKind','source-link');r[id].setdefault('sectionOverride','National final')
def new(id,year,num,statement):
 (extra/(id+'.json')).write_text(json.dumps({'slug':id,'country':'India','year':year,'competition':'Indian National Mathematical Olympiad (INMO)','section':'National final','problem_number':str(num),'problem_markdown':statement,'solutions_markdown':[],'topics':[],'primary_domain':'Algebra','sourceDataset':'HBCSE official archive','sourceLicense':'Original paraphrase; source rights retained','booklet_title':f'INMO {year} official problems and solutions'},indent=2))
 if not any((x[0] if isinstance(x,list) else x.get('slug',x.get('id')))==id for x in manifest):manifest.append({'slug':id,'country':'India','year':year,'competition':'Indian National Mathematical Olympiad (INMO)','number':str(num)})
add('ind_2017_f44f99',5,'The fold creates three similar right triangles. Expressing the square side in several ways forces an additive relation between the similarity factors.',topic='Geometry',subtopics=['Similarity & congruence','Triangle centres','Transformations'],numberOverride='1')
add('ind_2017_4d909c',4.5,'Vieta converts integer roots into a zero-sum triple. Their residues modulo 3 force a stronger product obstruction modulo 9.',r'''Let the roots be $u,v,w$. Vieta gives $u+v+w=0$ and $uvw=2\cdot2016^n-4$. If $n\ge1$, the product is $2$ modulo $3$, so none of the roots is divisible by $3$. A zero-sum triple of nonzero residues modulo $3$ must have all three residues equal; their product forces $u,v,w\equiv-1\pmod3$. Write $u=3a-1$, $v=3b-1$, $w=3c-1$. Then $a+b+c=1$, and $uvw\equiv-1+3(a+b+c)=2\pmod9$. But the required product is $-4\equiv5\pmod9$, a contradiction. Thus $n=0$, and the roots have product $-2$ and sum zero, forcing the multiset $\{1,1,-2\}$. Hence $\alpha=-3$, and $(x-1)^2(x+2)$ verifies it.''',topic='Number Theory',subtopics=['Modular arithmetic','Integer polynomials'],numberOverride='2')
new('ind_2017_inmo_q3_official',2017,3,r'Count all triples $(x,a,b)$ with $x\in\mathbb R$ and $a,b\in\{1,\ldots,9\}$ for which $x^2-a\{x\}+b=0$, where $\{x\}=x-\lfloor x\rfloor$.')
add('ind_2017_inmo_q3_official',4.5,'The fractional-part substitution requires an exact root-in-interval criterion before a short, symmetric count of integer cases.',r'''Put $x=n+t$, where $n\in\mathbb Z$ and $0\le t<1$. The equation is $P(t)=t^2+(2n-a)t+n^2+b=0$. Since $P(0)=n^2+b\ge1$, a root in $[0,1)$ must be positive. Its other root, whose product with it is $n^2+b$, is greater than $1$. Therefore there is exactly one admissible root precisely when $P(1)<0$, or $(n+1)^2+b<a$. This forces $n=-3,-2,-1,0,1$. For $n=-3,1$ there are $1+2+3+4=10$ pairs each; for $n=-2,0$ there are $1+\cdots+7=28$ each; for $n=-1$ there are $1+\cdots+8=36$. Thus the answer is $2(10)+2(28)+36=\boxed{112}$.''',topic='Algebra',subtopics=['Floors & fractional parts','Equations & systems'])
add('ind_2017_269854',5.5,'Converts the 120-degree geometry into two additive side relations and then classifies consecutive integer side sets.',topic='Geometry',subtopics=['Quadrilaterals & polygons','Similarity & congruence'],numberOverride='4')
add('ind_2017_fe2467',5.5,'Angle chasing identifies the large triangle incentre as the orthocentre of an auxiliary triangle; a 45-degree chord then gives the length equality.',topic='Geometry',subtopics=['Triangle centres','Angles & cyclic quadrilaterals'],numberOverride='5')
add('ind_2017_3d1044',4.5,'Recognising the even binomial terms as a quadratic-unit expansion produces a Pell identity, which makes both Heron expressions integral.',r'''Define the integer $y$ by $(2+\sqrt3)^n=x+y\sqrt3$. Conjugation gives $(2-\sqrt3)^n=x-y\sqrt3$, so $x^2-3y^2=1$. The displayed sum has $x\ge2$, hence the proposed sides satisfy the triangle inequalities. Their semiperimeter is $3x$, and Heron gives area $\Delta=\sqrt{3x(x+1)x(x-1)}=3xy$. The inradius is $\Delta/(3x)=y$. Both are integers.''',topic='Number Theory',subtopics=['Diophantine equations','Squares & powers'],numberOverride='6')
# Selection problems retain their distinct booklet identity.
tst={'competitionOverride':'Indian team selection tests','sectionOverride':'Selection problems'}
add('ind_2017_1717ae',6,'A rational symmetric sum is converted to a polynomial by the root recurrence; the final inequality uses a non-obvious grouping of elementary symmetric functions.',r'''Write $p=a+b+c$, $q=ab+bc+ca$, and $r=abc=1$, and let $S_k=\sum_{cyc}a^k/((a-b)(a-c))$. Direct common-denominator simplification gives $S_0=S_1=0$, $S_2=1$. Since each root satisfies $x^3-px^2+qx-r=0$, we have $S_k=pS_{k-1}-qS_{k-2}+rS_{k-3}$. Successive substitution yields $S_6=p^4-3p^2q+q^2+2pr=p^2(p^2-3q)+q^2+2p$. Distinctness gives $p^2-3q>0$, while AM-GM gives $p,q\ge3$. Thus $S_6>9+6=15$.''',topic='Algebra',subtopics=['Polynomials','Inequalities','Sequences & recurrences'],**tst)
add('ind_2017_ef8f74',4.5,'Chooses initial values to make the recurrence geometric modulo p, after splitting its characteristic polynomial using a square root of minus one.',r'''Choose $t$ with $t^2\equiv-1\pmod p$, which exists because $p\equiv1\pmod4$ (for example, pair the factors in Wilson's theorem). Put $m=1$, $n=t+2$. Then $n^2-4n+5\equiv0\pmod p$. Induction in the recurrence gives $a_k\equiv n^k\pmod p$. If $n\equiv0$, then $t\equiv-2$ and $p\mid5$, excluded by $p>5$. Hence no term is divisible by $p$.''',topic='Number Theory',subtopics=['Modular arithmetic','Sequences & recurrences'],**tst)
add('ind_2017_f587bb',6.5,'A weighted row-column count verifies Hall’s condition; finding and subtracting a perfect matching then gives the decomposition by induction.',r'''If the common sum is zero the empty sum suffices. Otherwise form a bipartite graph on rows and columns, joining row $i$ to column $j$ when $a_{ij}>0$. For any row subset $S$, its entries have total $m|S|$ and lie in the neighboring columns, whose full total is $m|N(S)|$. Thus $|N(S)|\ge|S|$. Hall's marriage theorem supplies a perfect matching. Subtract its permutation matrix; all entries remain nonnegative integers and every row and column sum becomes $m-1$. Repeating this step yields exactly $m$ permutation matrices.''',topic='Combinatorics',subtopics=['Graph theory','Double counting','Induction'],**tst)
add('ind_2017_5c912a',7.5,'Requires controlling odd root multiplicities of composed polynomials over the complex numbers, including the distinction between real and complex square factors.',**tst)
add('ind_2017_8680c5',None,'The available synthetic proof makes an unsupported inference from two points on a ray lying on one circle and contains inconsistent tangent and parallel-line claims.',omitReason='Held unrated: the supplied geometry proof has substantive gaps; a verified replacement or official solution is still required.',**tst)
add('ind_2017_ad91f1',3.5,'After dividing by x to the nth power, strict monotonicity gives uniqueness; the root recurrence and a geometric bound give monotonicity and the limit.',**tst)
# 2019
add('ind_2019_29d03e',5.5,'The tangent relation and an isosceles triangle give a similarity; sine-rule substitutions reduce the angle to a single double-angle equation.',topic='Geometry',subtopics=['Circles & tangency','Similarity & congruence','Trigonometry'])
add('ind_2019_52e2b0',4.5,'Recognises that the nested pentagons share five side directions, then combines an odd-cycle colouring observation with a two-stage pigeonhole argument.',r'''Every pentagon has a monochromatic side, since a two-colouring cannot alternate around an odd cycle. Midpoint pentagons remain concentric regular pentagons, and their side directions are the same five directions modulo $180^\circ$. Choose one monochromatic side from each of the eleven pentagons. Among the ten choices of direction and colour, two sides agree. Their midpoints lie on the same line through the common centre perpendicular to their direction, so their endpoints form an isosceles trapezoid. The four distinct endpoints therefore lie on one circle and have one colour.''',topic='Combinatorics',subtopics=['Pigeonhole principle','Colouring','Combinatorial geometry'])
add('ind_2019_a370ba',5,'Replaces the gcds by complementary divisors of the fixed difference; coprimality of adjacent terms gives the decisive product bounds, with equality tracked.',r'''Put $K=|m-n|$ and $d_j=\gcd(m+j,K)$ for $j=0,1,2$. Write $d_0=K/a$, $d_1=K/b$, $d_2=K/c$. Since $K\mid ma$ and $K\mid(m+1)b$, multiplying and subtracting shows $K\mid ab$; similarly $K\mid bc$. Thus $K/a\le b$ and $K/c\le b$, and
$$d_0+d_1+d_2\le2b+K/b\le2K+1.$$
The last inequality follows from $(K-b)(2b-1)\ge0$, since $1\le b\le K$. Equality requires $b=K$, $a=c=1$, hence $K\mid m,m+2$, so $K=1$ or $2$. These give respectively any consecutive pair, or two even integers differing by $2$; each indeed attains equality.''',topic='Number Theory',subtopics=['Divisibility & GCD'])
add('ind_2019_1c64a4',5.5,'Separates numbers with many prime factors from those with few, assigning a large prime power uniquely before a greedy completion.',r'''First handle every $M+j$ with at most $n-1$ distinct prime factors. Since $M+j>n^{n-1}$, some maximal prime-power factor $p^a$ exceeds $n$; assign $p$ to that number. Two such numbers cannot receive the same prime: the smaller of their selected prime powers would exceed $n$ and divide their nonzero difference, which is less than $n$. Now handle the remaining numbers in any order. Each has at least $n$ distinct prime factors, and at most $n-1$ primes have already been assigned, so an unused prime factor is always available. The resulting assignments are all distinct.''',topic='Number Theory',subtopics=['Primes','Divisibility & GCD','Valuations'])
add('ind_2019_f8a12e',5,'The excircle contact distance equals the semiperimeter, turning the hypothesis into a right-triangle power identity that proves internal tangency.',r'''Let $AD=d$, let $R$ be the radius of $\Gamma$, and let $r$ be the exradius opposite $A$. Take coordinates $A=(0,0)$, $D=(d,0)$ with $K$ above $AB$. The excentre is $M=(d+r,r)$, and its contact point $E$ on $AD$ extended satisfies $AE=d+r=s$, the semiperimeter. Thus $(d+r)^2=AC^2=AD\cdot AB=2Rd$. The centre of $\Gamma$ is $O=(R,0)$, so
$$OM^2=(d+r-R)^2+r^2=(R-r)^2.$$
Moreover $r=\sqrt{2Rd}-d\le R/2$, from $(\sqrt d-\sqrt{R/2})^2\ge0$. Therefore $OM=R-r$, proving internal tangency.''',topic='Geometry',subtopics=['Triangle centres','Circles & tangency','Coordinates & vectors'])
add('ind_2019_5478cf',5.5,'Multiplicativity gives reciprocal identities; substituting 1/x in the complement relation produces diagonal values, then polarisation gives reciprocity.',r'''Multiplicativity and positivity imply $f(1,t)=f(-1,t)=f(t,1)=f(t,-1)=1$ and $f(x^{-1},y)=f(x,y)^{-1}=f(x,y^{-1})$. For $x\ne0,1$, apply the complement relation to $1/x$ and invert its first argument. This gives $f(x,1-1/x)=1$. Hence
$$f(x,-x)=f\left(x,\frac{1-x}{1-1/x}\right)=1.$$
Since $f(x,-1)=1$, also $f(x,x)=1$; the case $x=1$ was already proved. Finally
$$1=f(xy,xy)=f(x,x)f(x,y)f(y,x)f(y,y)=f(x,y)f(y,x).$$''',topic='Algebra',subtopics=['Functional equations'],note='Uses the corrected official solution statement with multiplicativity in both arguments. The originally printed paper omitted a hypothesis, as acknowledged by HBCSE.')
# 2020
add('ind_2020_1d994f',7,'Several circumcentre angle relations must be coordinated: first one centre is equidistant, then an auxiliary cyclicity and bisector give the second.',topic='Geometry',subtopics=['Triangle centres','Angles & cyclic quadrilaterals','Circles & tangency'])
add('ind_2020_28e27a',5,'Two polynomial symmetries must be extracted from the trigonometric condition; shifting the squared variable makes the final evenness transparent.',r'''Compare the condition at $\theta$ and at $\pi/2-\theta$ to obtain $P(t)=P(-t)$ for all $t\in[-\sqrt2,\sqrt2]$. A polynomial vanishing on an interval is zero, so $P$ is even and $P(x)=Q(x^2)$. The original condition now says $Q(1+\sin2\theta)=Q(1-\sin2\theta)$; again polynomial identity extends this to all real inputs. Therefore $R(t)=Q(1+t)$ is even, say $R(t)=\sum a_kt^{2k}$. Thus $P(x)=R(x^2-1)=\sum a_k(1-x^2)^{2k}$.''',topic='Algebra',subtopics=['Polynomials','Trigonometry'])
add('ind_2020_9f83b1',5,'A five-digit construction is easy once found, but sharpness requires counting unordered sums modulo 10 and detecting an unavoidable parity collision.',r'''The set $\{0,1,3,4,6\}$ works: each decimal digit is a sum of two members without carrying (for $0,\ldots,9$ use $0+0,0+1,1+1,0+3,1+3,1+4,3+3,3+4,4+4,3+6$). Apply this separately to each digit.
If a four-element set worked, its ten unordered pairs with repetition would have to give the ten distinct residues modulo $10$. In particular exactly five sums would be odd. But if the set has $e$ even and $4-e$ odd elements, the number of odd unordered sums is $e(4-e)\le4$, contradiction. Smaller sets can be enlarged to four elements. Thus the minimum is $\boxed5$.''',topic='Number Theory',subtopics=['Digits & bases','Modular arithmetic','Parity'])
add('ind_2020_b8bee9',4.5,'Pairs ordered prefix products with ordered factors minus one; Chebyshev then turns the weighted sum into a telescoping product.',r'''Put $P_0=1$ and $P_k=a_1\cdots a_k$. Both sequences $P_0,\ldots,P_{n-1}$ and $a_1-1,\ldots,a_n-1$ are increasing. Chebyshev, together with $\sum(a_i-1)=n$, gives
$$\sum_{k=0}^{n-1}P_k\le\sum_{k=0}^{n-1}P_k(a_{k+1}-1)=\sum_{k=0}^{n-1}(P_{k+1}-P_k)=P_n-1.$$
Adding one yields the desired inequality.''',topic='Algebra',subtopics=['Inequalities','Sequences & recurrences'])
new('ind_2020_inmo_q5_official',2020,5,r'An infinite family of equally spaced parallel lines is fixed. Call $n\ge3$ frameable if some regular $n$-gon has one vertex on each of $n$ different lines. Prove that $3,4,6$ are frameable, that no $n\ge7$ is frameable, and decide the case $n=5$.')
add('ind_2020_inmo_q5_official',6.5,'A geometric descent constructs a smaller regular polygon from the edge vectors; the exceptional pentagon is ruled out by producing a decagon.',r'''Scale so the lines are $y\in\mathbb Z$. A regular hexagon of circumradius $1$, rotated by $30^\circ$, has heights $1/2,1,1/2,-1/2,-1,-1/2$, which repeat, so use instead a hexagon whose edge directions have vertical components proportional to $1,3,2,-1,-3,-2$: take edge vectors $(\sqrt3,1),(0,2),(-\sqrt3,1),(-\sqrt3,-1),(0,-2),(\sqrt3,-1)$, then apply a rotation with sine/cosine chosen so the distinct vertex heights are integral. An explicit choice is the regular hexagon with vertices $(4,0),(2,2\sqrt3),(-2,2\sqrt3),(-4,0),(-2,-2\sqrt3),(2,-2\sqrt3)$ and height functional $h(x,y)=x+y/\sqrt3$, giving heights $4,4,0,-4,-4,0$; choose instead $h=x+2y/\sqrt3$, giving $4,6,2,-4,-6,-2$, all distinct integers. Rotating and scaling identifies its level lines with the prescribed parallel lines. Alternate vertices give an equilateral triangle. For a square, vertices $(1,2),(-2,1),(-1,-2),(2,-1)$ already have distinct integral heights.

Now allow repeated heights, a weaker condition. From any regular $n$-gon on the integer-height lines, place all its edge vectors at a point of integral height. Their endpoints again have integral heights and form a regular $n$-gon whose side length is multiplied by $2\sin(\pi/n)$. For $n\ge7$ this factor is less than $1$. Iterating makes its diameter less than $1$, forcing every vertex onto one horizontal line, impossible for a regular polygon. For $n=5$, include both signs of every edge vector: their endpoints form a regular decagon on the same lines, already ruled out. Thus precisely $3,4,6$ are frameable.''',topic='Geometry',subtopics=['Transformations','Quadrilaterals & polygons','Extremal arguments'])
# simplify the explicit hexagon construction without abandoned trial formulae
r['ind_2020_inmo_q5_official']['solutionOverride']=r['ind_2020_inmo_q5_official']['solutionOverride'].replace(r'''A regular hexagon of circumradius $1$, rotated by $30^\circ$, has heights $1/2,1,1/2,-1/2,-1,-1/2$, which repeat, so use instead a hexagon whose edge directions have vertical components proportional to $1,3,2,-1,-3,-2$: take edge vectors $(\sqrt3,1),(0,2),(-\sqrt3,1),(-\sqrt3,-1),(0,-2),(\sqrt3,-1)$, then apply a rotation with sine/cosine chosen so the distinct vertex heights are integral. An explicit choice is the regular hexagon''',r'''Consider the regular hexagon''').replace(r'''and height functional $h(x,y)=x+y/\sqrt3$, giving heights $4,4,0,-4,-4,0$; choose instead $h=x+2y/\sqrt3$, giving''',r'''and the linear height coordinate $h(x,y)=x+2y/\sqrt3$. Its six height values are''')
add('ind_2020_278cd4',5.5,'One colour count locates the two singly covered cells in a residue class; a second independent colouring forces both into the unique central square.',r'''The total coverage is $48$, so exactly two of the $25$ cells are covered once and the rest twice. Colour cell $(i,j)$, $1\le i,j\le5$, by $i+j\pmod3$. Each stromino contains one of each colour; the class $0$ has nine cells and the others eight. Sixteen copies of each colour therefore force the two singly covered cells into class $0$. Repeat with the colouring $i-j\pmod3$, whose zero class again has nine cells. Both exceptional cells must satisfy $i+j\equiv i-j\equiv0\pmod3$, hence $i=j=3$. There cannot be two distinct exceptional cells at that single position.''',topic='Combinatorics',subtopics=['Colouring','Tilings & dissections','Counting'])
